{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '제가 그 정도밖에 안 되는 사람이라는 거요. 그냥 다들 그렇게 볼 것 같아요'라고 말하며, 가만히 앉아 있는 자신을 누군가 본다는 상상을 요청받았을 때의 두려움이 '충분하지 않다'는 핵심 신념과 직접 연결됨. 성장 배경에서 잘한 것은 언급되지 않고 부족한 것만 지적되던 경험이 이 신념의 기원."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '가만히 앉아 있는 나를 누군가 본다고 상상하면 어떤 표정이 떠오르세요'라고 질문한 것은, 기준을 낮추거나 쉬는 순간 타인이 자신의 부족함을 알아볼 것이라는 부정적 가정과 정확히 겹침. 성장 배경에서 성적이 곧 사람의 가치로 다뤄진 경험이 '느슨해지면 사람들이 그 정도밖에 안 되는 사람임을 알게 된다'는 가정을 형성."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 '가만히 있으면 불안해서 밀린 걸 찾아 한다'고 말한 것은 '쉬는 것은 그럴 자격을 갖춘 다음의 일이다'는 규칙이 작동하고 있음을 보여줌. 상황 사례에서 남편의 드라이브 제안을 거절하고 불안 속에 밤을 보낸 것이 이 규칙의 구체적 발현."
    },
    {
      "trait_id": "/coping_strategies/2",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 '가만히 있으면 불안해서 밀린 걸 찾아 하고, 그러다 보면 결국 또 하루가 다 가요'라고 한 진술이 이 대응 전략과 직접 일치함. 상담사의 '가만히 앉아 있는 나를 누군가 본다'는 상상은 이 전략이 작동하지 못하게 하는 상황을 상상하게 하는 질문."
    }
  ]
}

